import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Meta Functions as plugin-lib-* Crates","description":"","frontmatter":{"title":"Meta Functions as `plugin-lib-*` Crates","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"accepted","status_note":"Accepted — meta functions are five leaf crates; `run` is composition."},"headers":[],"relativePath":"handl/project/adrs/0047-meta-functions-as-plugin-lib-crates.md","filePath":"vendored/handl/project/adrs/0047-meta-functions-as-plugin-lib-crates.md"}'),a={name:`handl/project/adrs/0047-meta-functions-as-plugin-lib-crates.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0047-meta-functions-as-plugin-lib-crates" tabindex="-1">ADR-0047: Meta Functions as <code>plugin-lib-*</code> Crates <a class="header-anchor" href="#adr-0047-meta-functions-as-plugin-lib-crates" aria-label="Permalink to “ADR-0047: Meta Functions as plugin-lib-* Crates”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Five new leaf crates, one operation each</strong> — <code>eval</code>, <code>lex</code>, <code>parse</code>, <code>compile</code>, <code>run-compiled</code> — instead of traits on the runtime.</li><li><strong><code>handl-runtime</code> becomes the abstraction + <code>Runtime</code> impl</strong>; engines register by name.</li><li><strong><code>compile</code> / <code>run_compiled</code> are leaf-able</strong> via <code>CompiledHandle</code> and <code>CompiledArtifact</code>.</li><li><strong><code>run</code> is dropped</strong> — it is composition of the other operations, not a primitive.</li><li><strong><code>self</code> stays an ambient global</strong>, handed to the program.</li><li><strong>Scope types re-export from <code>plugin-lib-eval</code></strong>, so there is one type per concept.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Meta functions were traits attached to the runtime, so every engine and every lib had to know the runtime type. Leaf crates with one operation each follow the plugin model: a host registers operations by name and composes them.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep <code>run</code> as a primitive</strong> — it is <code>eval</code> + module composition.</li><li><strong>Keep meta traits on the runtime</strong> — they couple every lib to the runtime.</li><li><strong>Duplicate scope types per lib</strong> — re-export from <code>plugin-lib-eval</code>.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Five small crates replace a trait bundle; registration is by name.</li><li>Compiled programs travel as handles/artifacts, not closures.</li><li>Composition lives in handl, not in the runtime.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>crates/plugin-lib-lang-{eval,lex,parse,compile,run-compiled}/</code>.</li><li><code>handl-runtime/</code> — the abstraction and name registry.</li><li><code>plugin-lib-eval/</code> — the scope types.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The five crates, registration, handles/artifacts and the scope re-exports: +<a href="./../design/0047-meta-functions-as-plugin-lib-crates.html"><code>design/0047-meta-functions-as-plugin-lib-crates.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};